import ast
import pandas as pd
import seaborn as sns
def task_func(csv_file):
    df = pd.read_csv(csv_file)
    def _parse(x):
        if isinstance(x, dict):
            return x
        if pd.isna(x):
            return {}
        try:
            return ast.literal_eval(str(x))
        except Exception:
            return {}
    if 'dict_column' in df.columns:
        df['dict_column'] = df['dict_column'].apply(_parse)
        features = pd.DataFrame(df['dict_column'].tolist())
    else:
        features = pd.DataFrame()
    numeric_features = features.apply(pd.to_numeric, errors='coerce') if not features.empty else pd.DataFrame()
    if not numeric_features.empty:
        numeric_features = numeric_features.loc[:, numeric_features.notna().any()]
    if not numeric_features.empty:
        grid = sns.pairplot(numeric_features)
    else:
        numeric_df = df.select_dtypes(include='number')
        if not numeric_df.empty:
            grid = sns.pairplot(numeric_df)
        else:
            tmp = pd.DataFrame({'value': [0]*len(df) if len(df) > 0 else [0]})
            grid = sns.pairplot(tmp)
    return df, grid

import pandas as pd
import os
import numpy as np
import ast
def task_func(directory):
    try:
        entries = os.listdir(directory)
    except Exception:
        entries = []

    csv_files = []
    for name in entries:
        path = os.path.join(directory, name)
        if os.path.isfile(path) and name.lower().endswith('.csv'):
            csv_files.append(path)

    if not csv_files:
        empty_df = pd.DataFrame(columns=['email', 'list', 'sum', 'mean', 'median'])
        return empty_df, None

    target = max(csv_files, key=lambda p: len(os.path.basename(p)))
    df = pd.read_csv(target)

    def parse_list(x):
        if isinstance(x, str):
            try:
                return ast.literal_eval(x)
            except Exception:
                return []
        if isinstance(x, (list, tuple, np.ndarray)):
            return list(x)
        return []

    df['list'] = df['list'].apply(parse_list)

    def compute_stats(vals):
        try:
            arr = np.array(vals, dtype=float)
        except Exception:
            arr = np.array([], dtype=float)
        s = float(arr.sum()) if arr.size > 0 else 0.0
        m = float(arr.mean()) if arr.size > 0 else np.nan
        med = float(np.median(arr)) if arr.size > 0 else np.nan
        return s, m, med

    sums, means, medians = [], [], []
    for vals in df['list']:
        s, m, med = compute_stats(vals)
        sums.append(s)
        means.append(m)
        medians.append(med)

    df['sum'] = sums
    df['mean'] = means
    df['median'] = medians

    ax = None
    valid = df['median'].dropna()
    if not valid.empty:
        import matplotlib.pyplot as plt
        ax = valid.plot(kind='hist')

    return df, ax

